// made by website_blog/build_blog.py from src/admin_page.html - do not edit by hand
export default "<!doctype html>\n<html lang=\"en-GB\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Insights editor - NoResume</title>\n<link rel=\"icon\" href=\"/favicon.png\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap\">\n<style>\n:root { --teal: #17726B; --teal-d: #1A5F5F; --teal-l: #36C5C5; --ink: #17282A; --muted: #5E6B69; --line: rgba(23,114,107,.18); --card: #fff; --bg: #F8F6E6; --red: #B3261E; --amber: #9A6700; }\n* { box-sizing: border-box; }\nhtml, body { margin: 0; }\nbody { font-family: Poppins, system-ui, sans-serif; color: var(--ink); background: linear-gradient(180deg, #F8F6E6 0%, #FBE3CF 100%) fixed; min-height: 100vh; font-size: 15px; line-height: 1.5; }\nbutton, input, select, textarea { font: inherit; color: inherit; }\na { color: var(--teal); }\n.top { position: sticky; top: 0; z-index: 20; display: flex; align-items: center; gap: 14px; padding: 12px 22px; background: rgba(248,246,230,.92); backdrop-filter: blur(10px); border-bottom: 1px solid var(--line); }\n.top img { height: 26px; display: block; }\n.top h1 { margin: 0; font-size: 16px; font-weight: 600; color: var(--teal); }\n.top .me { margin-left: auto; font-size: 12.5px; color: var(--muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.top .me a { margin-left: 10px; }\n.wrap { display: grid; grid-template-columns: 300px 1fr; gap: 22px; max-width: 1280px; margin: 0 auto; padding: 22px; align-items: start; }\n.panel { background: var(--card); border-radius: 18px; box-shadow: 0 10px 30px rgba(6,27,64,.07); }\n.list { padding: 14px; position: sticky; top: 72px; max-height: calc(100vh - 94px); overflow: auto; }\n.list h2 { font-size: 13px; text-transform: uppercase; letter-spacing: .1em; color: var(--muted); margin: 14px 6px 6px; font-weight: 600; }\n.item { display: block; width: 100%; text-align: left; border: 0; background: none; padding: 10px 10px; border-radius: 12px; cursor: pointer; }\n.item:hover { background: rgba(23,114,107,.06); }\n.item.on { background: rgba(23,114,107,.12); }\n.item .t { font-weight: 600; font-size: 14px; line-height: 1.35; display: block; }\n.item .m { font-size: 12px; color: var(--muted); display: flex; gap: 8px; align-items: center; margin-top: 3px; }\n.pill { display: inline-block; font-size: 11px; font-weight: 600; letter-spacing: .04em; padding: 2px 9px; border-radius: 999px; }\n.pill.published { background: rgba(23,114,107,.14); color: var(--teal); }\n.pill.draft { background: rgba(154,103,0,.12); color: var(--amber); }\n.pill.archived { background: rgba(0,0,0,.07); color: var(--muted); }\n.pill.scheduled { background: rgba(54,197,197,.18); color: #0F5A54; }\n.btn { border: 0; border-radius: 999px; padding: 10px 20px; font-weight: 600; font-size: 14px; cursor: pointer; background: rgba(23,114,107,.1); color: var(--teal); white-space: nowrap; }\n.btn:hover { background: rgba(23,114,107,.18); }\n.btn.main { background: linear-gradient(135deg, var(--teal-d) 0%, var(--teal-l) 100%); color: #fff; box-shadow: 0 6px 18px rgba(26,95,95,.25); }\n.btn.main:hover { filter: brightness(1.05); }\n.btn.warn { background: rgba(179,38,30,.08); color: var(--red); }\n.btn:disabled { opacity: .5; cursor: default; }\n.btn.new { width: 100%; }\n.editor { padding: 26px 30px 30px; min-width: 0; }\n.empty { padding: 60px 30px; text-align: center; color: var(--muted); }\n.row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }\n.row3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 16px; }\nlabel.f { display: block; margin: 0 0 16px; }\nlabel.f > span { display: block; font-size: 12.5px; font-weight: 600; color: var(--muted); margin-bottom: 5px; }\nlabel.f > span small { font-weight: 400; }\ninput[type=text], input[type=url], input[type=date], select, textarea { width: 100%; border: 1.5px solid var(--line); border-radius: 12px; padding: 10px 13px; background: #fff; outline: none; }\ninput:focus, select:focus, textarea:focus, .body:focus { border-color: var(--teal-l); box-shadow: 0 0 0 3px rgba(54,197,197,.18); }\ninput.title { font-size: 22px; font-weight: 700; padding: 12px 14px; }\ntextarea { resize: vertical; min-height: 70px; }\n.slug { display: flex; align-items: center; border: 1.5px solid var(--line); border-radius: 12px; background: #fff; overflow: hidden; }\n.slug span { padding: 10px 0 10px 13px; color: var(--muted); white-space: nowrap; font-size: 14px; }\n.slug input { border: 0; box-shadow: none !important; padding-left: 2px; }\n.slug:focus-within { border-color: var(--teal-l); }\n.hint { font-size: 12px; color: var(--muted); margin-top: 4px; }\n.check { display: flex; gap: 10px; align-items: flex-start; margin: 4px 0 18px; font-size: 14px; cursor: pointer; }\n.check input { margin-top: 4px; width: 17px; height: 17px; accent-color: var(--teal); }\n.cover { display: flex; gap: 14px; align-items: center; flex-wrap: wrap; }\n.cover img { height: 84px; max-width: 220px; object-fit: cover; border-radius: 10px; box-shadow: 0 4px 14px rgba(6,27,64,.12); }\n.toolbar { position: sticky; top: 62px; z-index: 5; display: flex; flex-wrap: wrap; gap: 4px; padding: 6px; background: #fff; border: 1.5px solid var(--line); border-bottom: 0; border-radius: 12px 12px 0 0; }\n.toolbar button { border: 0; background: none; border-radius: 8px; padding: 6px 10px; cursor: pointer; font-size: 13.5px; font-weight: 500; color: var(--ink); }\n.toolbar button:hover { background: rgba(23,114,107,.1); }\n.toolbar .sep { width: 1px; background: var(--line); margin: 4px 4px; }\n.body { min-height: 380px; border: 1.5px solid var(--line); border-radius: 0 0 12px 12px; padding: 20px 24px; background: #fff; outline: none; font-size: 16.5px; line-height: 1.7; color: #24312F; overflow-wrap: anywhere; }\n.body:empty::before { content: 'Write or paste the article here. Pasting from LinkedIn keeps the paragraphs.'; color: #9AA5A3; }\n.body p { margin: 0 0 18px; }\n.body h2 { font-size: 1.45rem; color: var(--teal); margin: 28px 0 12px; line-height: 1.25; }\n.body h3 { font-size: 1.15rem; margin: 22px 0 10px; }\n.body blockquote { margin: 22px 0; padding: 16px 20px; background: rgba(23,114,107,.06); border-left: 4px solid var(--teal); border-radius: 12px; font-weight: 600; }\n.body img { max-width: 100%; height: auto; display: block; margin: 0 auto; border-radius: 12px; }\n.body figure { margin: 22px 0; }\n.body figcaption { font-size: 13px; color: var(--muted); text-align: center; margin-top: 8px; }\n.body ul, .body ol { margin: 0 0 18px; padding-left: 24px; }\n:is(.body, .tprev) table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 15px; line-height: 1.35; font-variant-numeric: tabular-nums; }\n:is(.body, .tprev) caption { caption-side: top; text-align: left; margin: 0 0 10px; font-weight: 700; color: var(--ink); }\n:is(.body, .tprev) :is(th, td) { padding: 9px 10px; text-align: right; border-bottom: 1px solid var(--line); }\n:is(.body, .tprev) :is(th, td):first-child { text-align: left; }\n:is(.body, .tprev) thead th { background: #1C7A73; color: #fff; font-weight: 600; font-size: 13.5px; border-bottom: 0; }\n:is(.body, .tprev) tbody td { font-weight: 700; }\n:is(.body, .tprev) tfoot :is(th, td) { border-top: 2px solid var(--teal); border-bottom: 0; font-weight: 700; }\n:is(.body, .tprev) th small { display: block; font-size: 12px; font-weight: 400; color: var(--muted); }\n:is(.body, .tprev) figure:has(> table) figcaption { text-align: left; color: var(--teal); font-weight: 600; }\n#tableDlg { border: 0; border-radius: 18px; padding: 0; width: min(760px, calc(100vw - 24px)); max-height: calc(100vh - 24px); overflow-y: auto; overscroll-behavior: contain; color: var(--ink); box-shadow: 0 30px 80px rgba(6,27,64,.25); }\n#tableDlg::backdrop { background: rgba(23,40,42,.35); }\n.dlg { padding: 24px 26px; }\n.dlg h2 { margin: 0 0 4px; font-size: 18px; color: var(--teal); }\n.dlg > .hint { margin: 0 0 18px; font-size: 13px; }\n.dlg textarea.cells { font-family: ui-monospace, Menlo, monospace; font-size: 13px; white-space: pre; overflow-x: auto; }\n.tprev { margin: 0 0 16px; padding: 16px; border: 1.5px dashed var(--line); border-radius: 12px; overflow-x: auto; font-size: 15px; }\n.tprev:empty { display: none; }\n.tprev ul { margin: 0 0 14px; padding-left: 22px; }\n.tprev figure { margin: 0; }\n.tprev figcaption { font-size: 13px; margin-top: 8px; }\n.dlg-actions { display: flex; gap: 10px; justify-content: flex-end; }\n.actions { position: sticky; bottom: 0; z-index: 10; display: flex; flex-wrap: wrap; gap: 10px; align-items: center; margin: 22px -30px -30px; padding: 16px 30px; background: #fff; box-shadow: 0 -6px 18px rgba(6,27,64,.06); border-top: 1px solid var(--line); border-radius: 0 0 18px 18px; }\n.actions .status { font-size: 13px; color: var(--muted); margin-right: auto; }\n.actions .status b { color: var(--ink); font-weight: 600; }\n.banner { display: none; margin: 0 0 18px; padding: 12px 16px; border-radius: 12px; font-size: 14px; }\n.banner.err { display: block; background: rgba(179,38,30,.08); color: var(--red); }\n.banner.ok { display: block; background: rgba(23,114,107,.1); color: var(--teal); }\n.back { display: none; }\n.busy { position: fixed; inset: 0; background: rgba(248,246,230,.5); display: none; z-index: 50; cursor: progress; }\n.busy.on { display: block; }\n@media (max-width: 900px) {\n  .wrap { grid-template-columns: 1fr; padding: 12px; }\n  .list { position: static; max-height: none; }\n  .wrap.editing .list { display: none; }\n  .wrap:not(.editing) .editor-panel { display: none; }\n  .back { display: inline-block; margin-bottom: 14px; }\n  .editor { padding: 18px 16px 20px; }\n  .row, .row3 { grid-template-columns: 1fr; gap: 0; }\n  .actions { margin: 18px -16px -20px; padding: 10px 16px; gap: 8px; }\n  .actions .status { width: 100%; font-size: 12px; }\n  .actions .status .by { display: none; }\n  .actions .btn { flex: 1 1 auto; padding: 9px 12px; font-size: 13px; }\n  .toolbar { top: 56px; }\n  .top .me span { display: none; }\n}\n</style>\n</head>\n<body>\n<div class=\"top\">\n  <img src=\"/assets/images/noresume_logo-color-orange.png\" alt=\"NoResume\">\n  <h1>Insights editor</h1>\n  <div class=\"me\"><span>Signed in as __EMAIL__</span><a href=\"/blog\" target=\"_blank\" rel=\"noopener\">View Insights \u2197</a></div>\n</div>\n\n<div class=\"wrap\" id=\"wrap\">\n  <aside class=\"panel list\">\n    <button class=\"btn main new\" id=\"newBtn\" type=\"button\">+ New article</button>\n    <div id=\"list\"></div>\n  </aside>\n\n  <main class=\"panel editor-panel\">\n    <div class=\"empty\" id=\"empty\">Pick an article on the left, or start a new one.</div>\n    <form class=\"editor\" id=\"form\" autocomplete=\"off\" hidden>\n      <button class=\"btn back\" type=\"button\" id=\"backBtn\">\u2190 All articles</button>\n      <div class=\"banner\" id=\"banner\"></div>\n\n      <label class=\"f\"><span>Title</span><input type=\"text\" class=\"title\" id=\"title\" maxlength=\"200\" placeholder=\"The better the job pays, the less likely the advert tells you\"></label>\n\n      <label class=\"f\"><span>Web address</span>\n        <div class=\"slug\"><span>noresume.co/blog/</span><input type=\"text\" id=\"slug\" maxlength=\"90\"></div>\n        <div class=\"hint\" id=\"slugHint\">Made from the title. It cannot change once the article is published.</div>\n      </label>\n\n      <label class=\"f\"><span>Summary <small>(1 or 2 sentences: shown on the card, under the title, and in LinkedIn / Google previews)</small></span>\n        <textarea id=\"excerpt\" maxlength=\"400\" rows=\"2\"></textarea>\n        <div class=\"hint\"><span id=\"excerptCount\">0</span> / 400 characters (about 160 reads best)</div>\n      </label>\n\n      <div class=\"row3\">\n        <label class=\"f\"><span>Category</span>\n          <select id=\"category\"><option>Hiring</option><option>Talent</option><option>Product</option></select></label>\n        <label class=\"f\"><span>Author</span>\n          <input type=\"text\" id=\"author\" list=\"authors\" maxlength=\"80\">\n          <datalist id=\"authors\"><option value=\"Simon Marsh\"><option value=\"Erika Ziranu\"><option value=\"The NoResume Team\"></datalist></label>\n        <label class=\"f\"><span>Date shown <small>(a future date publishes it then)</small></span>\n          <input type=\"date\" id=\"date\"></label>\n      </div>\n\n      <label class=\"check\"><input type=\"checkbox\" id=\"featured\"> <span>Featured: show as the big card at the top of Insights (only one article at a time)</span></label>\n\n      <label class=\"f\"><span>Top picture <small>(optional: shown above the article and on its card)</small></span>\n        <div class=\"cover\">\n          <img id=\"coverImg\" alt=\"\" hidden>\n          <button class=\"btn\" type=\"button\" id=\"coverBtn\">Choose picture</button>\n          <button class=\"btn warn\" type=\"button\" id=\"coverDel\" hidden>Remove</button>\n          <input type=\"file\" id=\"coverFile\" accept=\"image/jpeg,image/png,image/webp,image/gif\" hidden>\n        </div>\n      </label>\n      <label class=\"f\" id=\"captionRow\" hidden><span>Picture caption <small>(optional)</small></span><input type=\"text\" id=\"caption\" maxlength=\"300\"></label>\n\n      <label class=\"f\"><span>Article</span></label>\n      <div class=\"toolbar\" id=\"toolbar\">\n        <button type=\"button\" data-cmd=\"p\" title=\"Normal text\">Text</button>\n        <button type=\"button\" data-cmd=\"h2\" title=\"Heading\">Heading</button>\n        <button type=\"button\" data-cmd=\"h3\" title=\"Smaller heading\">Subheading</button>\n        <span class=\"sep\"></span>\n        <button type=\"button\" data-cmd=\"bold\" title=\"Bold (Ctrl/Cmd+B)\"><b>B</b></button>\n        <button type=\"button\" data-cmd=\"italic\" title=\"Italic (Ctrl/Cmd+I)\"><i>I</i></button>\n        <button type=\"button\" data-cmd=\"link\" title=\"Link\">Link</button>\n        <span class=\"sep\"></span>\n        <button type=\"button\" data-cmd=\"ul\" title=\"Bulleted list\">\u2022 List</button>\n        <button type=\"button\" data-cmd=\"ol\" title=\"Numbered list\">1. List</button>\n        <button type=\"button\" data-cmd=\"quote\" title=\"Highlighted quote\">Quote</button>\n        <button type=\"button\" data-cmd=\"image\" title=\"Add a picture\">Picture</button>\n        <button type=\"button\" data-cmd=\"table\" title=\"Add a data table: the figures as text, so Google and AI tools can read and quote them\">Table</button>\n        <span class=\"sep\"></span>\n        <button type=\"button\" data-cmd=\"clear\" title=\"Remove bold, italic and links from the selection\">Clear</button>\n        <button type=\"button\" data-cmd=\"undo\" title=\"Undo (Ctrl/Cmd+Z)\">\u21b6</button>\n      </div>\n      <div class=\"body\" id=\"body\" contenteditable=\"true\" spellcheck=\"true\"></div>\n      <input type=\"file\" id=\"bodyFile\" accept=\"image/jpeg,image/png,image/webp,image/gif\" hidden>\n      <div class=\"hint\" id=\"words\">0 words \u00b7 1 min read</div>\n\n      <label class=\"f\" style=\"margin-top:18px\"><span>Original LinkedIn post <small>(optional: adds \"First posted on LinkedIn\" at the end)</small></span>\n        <input type=\"url\" id=\"original\" placeholder=\"https://www.linkedin.com/posts/...\"></label>\n\n      <div class=\"actions\" id=\"actions\">\n        <div class=\"status\" id=\"status\"></div>\n      </div>\n    </form>\n  </main>\n</div>\n<dialog id=\"tableDlg\">\n  <div class=\"dlg\">\n    <h2>Add a data table</h2>\n    <p class=\"hint\">Puts the figures into the article as text, so Google and AI tools can read and quote them. Keep the table picture as well: that is what LinkedIn shows.</p>\n    <label class=\"f\"><span>Table title <small>(what the numbers are, UK, month)</small></span>\n      <input type=\"text\" id=\"tTitle\" maxlength=\"200\" placeholder=\"UK employers that put the pay in their job adverts, October 2026\"></label>\n    <label class=\"f\"><span>Table <small>(copy the cells from a spreadsheet and paste them here, or paste a whole table file)</small></span>\n      <textarea id=\"tData\" class=\"cells\" rows=\"8\" spellcheck=\"false\"></textarea>\n      <div class=\"hint\">First row = column headings. A last row starting \"All\" or \"Total\" becomes the total row. For a small second line under a row name, put | between them: Minimum wage | under \u00a327k a year</div></label>\n    <label class=\"f\"><span>Key points <small>(optional, one per line: shown above the table as bullets)</small></span>\n      <textarea id=\"tPoints\" rows=\"3\"></textarea></label>\n    <label class=\"f\"><span>Source line</span><input type=\"text\" id=\"tSource\" maxlength=\"120\" value=\"Source: NoResume\"></label>\n    <div class=\"banner\" id=\"tErr\"></div>\n    <div class=\"tprev\" id=\"tPrev\"></div>\n    <div class=\"dlg-actions\">\n      <button class=\"btn\" type=\"button\" id=\"tCancel\">Cancel</button>\n      <button class=\"btn main\" type=\"button\" id=\"tAdd\">Add to article</button>\n    </div>\n  </div>\n</dialog>\n<form id=\"previewForm\" method=\"post\" action=\"/admin/preview\" target=\"_blank\" hidden><input type=\"hidden\" name=\"data\" id=\"previewData\"></form>\n<div class=\"busy\" id=\"busy\"></div>\n\n<script>\n(function () {\n  'use strict';\n  var $ = function (id) { return document.getElementById(id); };\n  var state = { me: '', posts: [], post: null, dirty: false, slugTouched: false, origDate: '' };\n\n  // \u2500\u2500 server \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  function api(path, body) {\n    var opts = body ? { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-NR-Admin': '1' }, body: JSON.stringify(body) } : {};\n    return fetch('/admin/api/' + path, opts).then(function (r) {\n      return r.json().catch(function () { return { error: 'The server sent something unexpected (' + r.status + ').' }; })\n        .then(function (j) { if (!r.ok || j.error) throw new Error(j.error || ('Error ' + r.status)); return j; });\n    }, function () { throw new Error('No connection. Check the internet and try again.'); });\n  }\n  function busy(on) { $('busy').classList.toggle('on', !!on); }\n  function banner(msg, ok) { var b = $('banner'); b.textContent = msg || ''; b.className = 'banner' + (msg ? (ok ? ' ok' : ' err') : ''); if (msg && !ok) b.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); }\n\n  // \u2500\u2500 list \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  function fmt(iso, withTime) {\n    if (!iso) return '';\n    var d = new Date(iso);\n    var s = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'Europe/London' });\n    return withTime ? s + ', ' + d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/London' }) : s;\n  }\n  function statusOf(p) {\n    if (p.status === 'published' && p.published_at && new Date(p.published_at) > new Date()) return 'scheduled';\n    return p.status;\n  }\n  var LABEL = { published: 'Live', draft: 'Draft', archived: 'Archived', scheduled: 'Scheduled' };\n  function drawList() {\n    var groups = { live: [], draft: [], archived: [] }, el = $('list');\n    state.posts.forEach(function (p) { groups[p.status === 'published' ? 'live' : p.status].push(p); });\n    el.innerHTML = '';\n    [['live', 'On the website'], ['draft', 'Drafts'], ['archived', 'Archived']].forEach(function (g) {\n      if (!groups[g[0]].length) return;\n      var h = document.createElement('h2'); h.textContent = g[1]; el.appendChild(h);\n      groups[g[0]].forEach(function (p) {\n        var b = document.createElement('button'); b.type = 'button'; b.className = 'item' + (state.post && state.post.id === p.id ? ' on' : '');\n        var t = document.createElement('span'); t.className = 't'; t.textContent = p.title || 'Untitled article';\n        var m = document.createElement('span'); m.className = 'm';\n        var pill = document.createElement('span'); var st = statusOf(p); pill.className = 'pill ' + st; pill.textContent = LABEL[st];\n        var when = document.createElement('span'); when.textContent = (p.featured ? '\u2605 ' : '') + fmt(p.published_at || p.updated_at);\n        m.appendChild(pill); m.appendChild(when); b.appendChild(t); b.appendChild(m);\n        b.onclick = function () { open(p.id); };\n        el.appendChild(b);\n      });\n    });\n    if (!state.posts.length) { var e = document.createElement('p'); e.className = 'hint'; e.style.padding = '10px'; e.textContent = 'No articles yet.'; el.appendChild(e); }\n  }\n  function loadList() {\n    return api('list').then(function (j) { state.me = j.me; state.posts = j.posts || []; drawList(); });\n  }\n\n  // \u2500\u2500 editor \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  function slugify(s) {\n    s = String(s || '').toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/&/g, ' and ').replace(/['\u2019]/g, '')\n      .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');\n    if (s.length > 80) s = s.slice(0, 80).replace(/-[^-]*$/, '');\n    return s;\n  }\n  function toEditor(html) { return String(html || '').replace(/\\/blog\\/img\\//g, '/admin/img/'); }\n  function fromEditor(html) { return String(html || '').replace(/\\/admin\\/img\\//g, '/blog/img/'); }\n  function countWords() {\n    var n = ($('body').innerText || '').split(/\\s+/).filter(Boolean).length;\n    $('words').textContent = n + ' words \u00b7 ' + Math.max(1, Math.round(n / 200)) + ' min read';\n  }\n  function setCover(id) {\n    state.coverId = id || null;\n    $('coverImg').hidden = !id; if (id) $('coverImg').src = '/admin/img/' + id;\n    $('coverDel').hidden = !id; $('captionRow').hidden = !id;\n    $('coverBtn').textContent = id ? 'Change picture' : 'Choose picture';\n  }\n  function fill(p) {\n    state.post = p; state.slugTouched = !!(p.id && p.slug); state.dirty = false;\n    $('title').value = p.title || ''; $('slug').value = p.slug || ''; $('excerpt').value = p.excerpt || '';\n    $('category').value = p.category || 'Hiring'; $('author').value = p.author_name || state.me || 'The NoResume Team';\n    state.origDate = p.published_at ? new Date(p.published_at).toLocaleDateString('en-CA', { timeZone: 'Europe/London' }) : '';\n    $('date').value = state.origDate;\n    $('featured').checked = !!p.featured; $('original').value = p.original_url || ''; $('caption').value = p.cover_caption || '';\n    setCover(p.cover_image_id);\n    $('body').innerHTML = toEditor(p.body_html);\n    $('slug').readOnly = p.status === 'published';\n    $('slugHint').textContent = p.status === 'published' ? 'Published articles keep their address, so links to them never break.' : 'Made from the title. It cannot change once the article is published.';\n    $('excerptCount').textContent = $('excerpt').value.length;\n    countWords(); banner(''); drawActions(); drawList();\n    $('empty').hidden = true; $('form').hidden = false; $('wrap').classList.add('editing');\n    window.scrollTo(0, 0);\n  }\n  function collect() {\n    var p = state.post || {};\n    var date = $('date').value;\n    return {\n      id: p.id || null, updated_at: p.updated_at || null,\n      title: $('title').value.trim(), slug: $('slug').value.trim() || slugify($('title').value),\n      excerpt: $('excerpt').value.trim(), category: $('category').value, author_name: $('author').value.trim(),\n      published_at: date ? (date === state.origDate ? p.published_at : date + 'T09:00:00Z') : (p.published_at || null),\n      featured: $('featured').checked, original_url: $('original').value.trim(),\n      cover_image_id: state.coverId || null, cover_caption: $('caption').value.trim(),\n      body_html: fromEditor(cleanHtml($('body').innerHTML))\n    };\n  }\n  function drawActions() {\n    var p = state.post || {}, a = $('actions'), st = p.id ? statusOf(p) : 'new';\n    a.querySelectorAll('button').forEach(function (b) { b.remove(); });\n    function add(label, cls, fn) { var b = document.createElement('button'); b.type = 'button'; b.className = 'btn ' + (cls || ''); b.textContent = label; b.onclick = fn; a.appendChild(b); }\n    var s = $('status');\n    if (!p.id) s.innerHTML = '<b>New article</b>, not saved yet';\n    else s.innerHTML = '<b>' + LABEL[st] + '</b> \u00b7 saved ' + fmt(p.updated_at, true) + '<span class=\"by\"> by ' + esc(p.updated_by || '') + '</span>';\n    if (state.dirty) s.innerHTML += ' \u00b7 <b style=\"color:#9A6700\">unsaved changes</b>';\n    add('Preview', '', preview);\n    if (p.status === 'published') {\n      add('Unpublish', 'warn', function () { if (confirm('Take this article off the website? It goes back to Drafts.')) save('unpublish'); });\n      add('Update live article', 'main', function () { save('save'); });\n    } else if (p.status === 'archived') {\n      add('Move back to Drafts', 'main', function () { save('restore'); });\n    } else {\n      if (p.id) add('Archive', 'warn', function () { if (confirm('Archive this draft? It is kept, just moved out of the way.')) save('archive'); });\n      add('Save draft', '', function () { save('save'); });\n      add('Publish', 'main', function () {\n        var future = $('date').value && new Date($('date').value + 'T09:00:00Z') > new Date();\n        if (confirm(future ? 'Publish on ' + $('date').value + '? It appears on the website that day.' : 'Publish this article on noresume.co now?')) save('publish');\n      });\n    }\n  }\n  function esc(s) { return String(s).replace(/[&<>\"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]; }); }\n  function save(action) {\n    var post = collect();\n    if (!post.slug) { banner('Give the article a title first.'); return; }\n    busy(true); banner('');\n    return api('save', { post: post, action: action }).then(function (p) {\n      state.dirty = false;\n      var msg = { publish: 'Published. It is on the website now (it can take up to a minute everywhere).', unpublish: 'Taken off the website and moved to Drafts.',\n                  archive: 'Archived.', restore: 'Moved back to Drafts.', save: p.status === 'published' ? 'Live article updated.' : 'Draft saved.' }[action];\n      return loadList().then(function () { fill(p); banner(msg, true); });\n    }).catch(function (e) { banner(e.message); }).then(function () { busy(false); });\n  }\n  function open(id) {\n    if (state.dirty && !confirm('You have unsaved changes. Leave them?')) return;\n    busy(true);\n    api('post?id=' + encodeURIComponent(id)).then(fill).catch(function (e) { alert(e.message); }).then(function () { busy(false); });\n  }\n  function preview() {\n    $('previewData').value = JSON.stringify(collect());\n    $('previewForm').submit();\n  }\n  function markDirty() { if (!state.dirty) { state.dirty = true; drawActions(); } }\n\n  // \u2500\u2500 pictures: made smaller in the browser before upload (long side 1600 px) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  function upload(file) {\n    if (!file) return Promise.reject(new Error('No file'));\n    if (!/^image\\/(jpeg|png|webp|gif)$/.test(file.type)) return Promise.reject(new Error('Use a JPEG, PNG, WebP or GIF picture.'));\n    busy(true);\n    return new Promise(function (resolve, reject) {\n      var img = new Image(), url = URL.createObjectURL(file);\n      img.onload = function () {\n        var w = img.naturalWidth, h = img.naturalHeight, max = 1600;\n        var keep = file.type === 'image/gif' || (Math.max(w, h) <= max && file.size <= 1.5e6);\n        if (keep) { blobToB64(file).then(function (b64) { resolve({ mime: file.type, b64: b64, width: w, height: h }); }, reject); return; }\n        var k = Math.min(1, max / Math.max(w, h)), cw = Math.round(w * k), ch = Math.round(h * k);\n        var c = document.createElement('canvas'); c.width = cw; c.height = ch;\n        var x = c.getContext('2d'); x.fillStyle = '#fff'; x.fillRect(0, 0, cw, ch); x.drawImage(img, 0, 0, cw, ch);\n        var webp = c.toDataURL('image/webp').indexOf('data:image/webp') === 0, mime = webp ? 'image/webp' : 'image/jpeg';\n        c.toBlob(function (b) { blobToB64(b).then(function (b64) { resolve({ mime: mime, b64: b64, width: cw, height: ch }); }, reject); }, mime, 0.9);\n      };\n      img.onerror = function () { reject(new Error('That picture could not be read.')); };\n      img.src = url;\n    }).then(function (pic) {\n      if (pic.b64.length > 5.5e6) throw new Error('That picture is too big (over 4 MB even after shrinking).');\n      return api('image', pic).then(function (j) { return { id: j.id, width: pic.width, height: pic.height }; });\n    }).then(function (r) { busy(false); return r; }, function (e) { busy(false); throw e; });\n  }\n  function blobToB64(b) {\n    return new Promise(function (res, rej) { var r = new FileReader(); r.onload = function () { res(String(r.result).split(',')[1]); }; r.onerror = rej; r.readAsDataURL(b); });\n  }\n\n  // \u2500\u2500 tidy pasted / typed HTML down to what articles use \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  var KEEP = { P: 1, BR: 1, H2: 1, H3: 1, STRONG: 1, EM: 1, U: 1, A: 1, UL: 1, OL: 1, LI: 1, BLOCKQUOTE: 1, FIGURE: 1, FIGCAPTION: 1, IMG: 1, HR: 1,\n               TABLE: 1, CAPTION: 1, THEAD: 1, TBODY: 1, TFOOT: 1, TR: 1, TH: 1, TD: 1, SMALL: 1 };\n  var RENAME = { B: 'STRONG', I: 'EM', H1: 'H2', H4: 'H3', H5: 'H3', H6: 'H3' };\n  var DROP = /^(SCRIPT|STYLE|IFRAME|OBJECT|EMBED|NOSCRIPT|TEMPLATE|SVG|MATH|FORM|INPUT|BUTTON|TEXTAREA|SELECT|HEAD|TITLE|META|LINK|BASE|VIDEO|AUDIO|CANVAS)$/;\n  var BLOCK = /^(P|DIV|H[1-6]|UL|OL|LI|BLOCKQUOTE|FIGURE|TABLE|SECTION|ARTICLE|HEADER|FOOTER)$/;\n  function cleanNode(node, out) {\n    Array.prototype.forEach.call(node.childNodes, function (n) {\n      if (n.nodeType === 3) { out.appendChild(document.createTextNode(n.nodeValue)); return; }\n      if (n.nodeType !== 1) return;\n      var tag = n.tagName.toUpperCase();\n      if (DROP.test(tag)) return;\n      if (tag === 'SPAN' && /font-weight:\\s*(bold|[6-9]00)/i.test(n.getAttribute('style') || '')) tag = 'STRONG';\n      if (tag === 'DIV' && !Array.prototype.some.call(n.children, function (c) { return BLOCK.test(c.tagName.toUpperCase()); })) tag = 'P';\n      tag = RENAME[tag] || tag;\n      if (!KEEP[tag]) { cleanNode(n, out); return; }\n      var el = document.createElement(tag);\n      if (tag === 'A') {\n        var href = (n.getAttribute('href') || '').trim();\n        if (/^(https?:\\/\\/|mailto:|\\/(?!\\/))/i.test(href)) el.setAttribute('href', href);\n      }\n      if (tag === 'IMG') {\n        var src = n.getAttribute('src') || '';\n        if (!/^\\/(admin|blog)\\/img\\/[0-9a-f-]{36}$/.test(src)) return;\n        el.setAttribute('src', src); el.setAttribute('alt', n.getAttribute('alt') || '');\n      }\n      if (tag === 'TH' && /^(row|col)$/i.test(n.getAttribute('scope') || '')) el.setAttribute('scope', n.getAttribute('scope').toLowerCase());\n      cleanNode(n, el);\n      if (tag === 'P' && !el.textContent.trim() && !el.querySelector('img,br')) return;\n      out.appendChild(el);\n    });\n    return out;\n  }\n  function cleanHtml(html) {\n    var doc = new DOMParser().parseFromString('<body>' + html + '</body>', 'text/html');\n    var out = cleanNode(doc.body, document.createElement('div'));\n    // loose text and inline bits at the top level go into paragraphs\n    var fixed = document.createElement('div'), para = null;\n    Array.prototype.slice.call(out.childNodes).forEach(function (n) {\n      var inline = n.nodeType === 3 || /^(STRONG|EM|U|A|BR|IMG)$/.test(n.tagName);\n      if (inline) {\n        if (n.nodeType === 3 && !n.nodeValue.trim() && !para) return;\n        if (!para) { para = document.createElement('p'); fixed.appendChild(para); }\n        para.appendChild(n);\n      } else { para = null; fixed.appendChild(n); }\n    });\n    fixed.querySelectorAll('table').forEach(tidyTable);\n    return fixed.innerHTML;\n  }\n  // a table pasted from a spreadsheet arrives as plain cells: first row -> headings, first cell of each row -> row\n  // name, a last row starting \"All\" / \"Total\" -> total row. Tables made with the Table button already have these.\n  function tidyTable(t) {\n    Array.prototype.forEach.call(t.querySelectorAll('tr'), function (tr) { if (!tr.textContent.trim()) tr.remove(); });\n    if (!t.querySelector('tr')) { t.remove(); return; }\n    if (!t.tHead) {\n      var first = t.querySelector('tr'), head = t.createTHead(), hr = head.insertRow();\n      Array.prototype.forEach.call(first.cells, function (c) { var th = document.createElement('th'); th.setAttribute('scope', 'col'); th.innerHTML = c.innerHTML; hr.appendChild(th); });\n      first.remove();\n    }\n    var body = t.tBodies[0];\n    if (!body) { body = t.createTBody(); Array.prototype.forEach.call(t.querySelectorAll(':scope > tr'), function (tr) { body.appendChild(tr); }); }\n    Array.prototype.forEach.call(t.querySelectorAll('tbody tr, tfoot tr'), function (tr) {\n      var c = tr.cells[0];\n      if (c && c.tagName === 'TD') { var th = document.createElement('th'); th.setAttribute('scope', 'row'); th.innerHTML = c.innerHTML; tr.replaceChild(th, c); }\n    });\n    var rows = body.rows, last = rows[rows.length - 1];\n    if (!t.tFoot && rows.length > 2 && /^\\s*(all|total)\\b/i.test(last.cells[0].textContent)) t.createTFoot().appendChild(last);\n  }\n\n  // \u2500\u2500 data tables: pasted spreadsheet cells (tab separated) or a table file -> table HTML \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  // table file lines \"TITLE<tab>...\", \"POINT<tab>...\", \"SOURCE<tab>...\" fill the boxes; the other lines are the cells\n  function splitRow(line) {\n    if (line.indexOf('\\t') >= 0) return line.split('\\t');\n    var out = [], cur = '', q = false;                                  // CSV, with \"quoted, cells\"\n    for (var i = 0; i < line.length; i++) {\n      var ch = line[i];\n      if (q) { if (ch === '\"' && line[i + 1] === '\"') { cur += '\"'; i++; } else if (ch === '\"') q = false; else cur += ch; }\n      else if (ch === '\"') q = true; else if (ch === ',') { out.push(cur); cur = ''; } else cur += ch;\n    }\n    out.push(cur); return out;\n  }\n  function rowName(s) {\n    var parts = String(s).split('|');\n    var main = esc(parts[0].trim()), sub = parts.slice(1).join('|').trim();\n    return sub ? main + '<small>' + esc(sub) + '</small>' : main;\n  }\n  function buildTable(title, data, points, source) {\n    var lines = String(data).replace(/\\r/g, '').split('\\n').filter(function (l) { return l.trim(); });\n    if (!title.trim()) throw new Error('Give the table a title: what the numbers are, UK, month.');\n    if (lines.length < 2) throw new Error('Paste at least a heading row and one row of figures.');\n    var rows = lines.map(function (l) { return splitRow(l).map(function (c) { return c.trim(); }); });\n    var cols = Math.max.apply(null, rows.map(function (r) { return r.length; }));\n    if (cols < 2) throw new Error('The table needs at least two columns. Copy the cells straight from the spreadsheet (they are separated by tabs).');\n    rows.forEach(function (r) { while (r.length < cols) r.push(''); });\n    var head = rows[0], bodyRows = rows.slice(1), foot = null;\n    if (bodyRows.length > 1 && /^\\s*(all|total)\\b/i.test(bodyRows[bodyRows.length - 1][0])) foot = bodyRows.pop();\n    function tr(r) { return '<tr><th scope=\"row\">' + rowName(r[0]) + '</th>' + r.slice(1).map(function (c) { return '<td>' + esc(c) + '</td>'; }).join('') + '</tr>'; }\n    var pts = String(points).split('\\n').map(function (p) { return p.replace(/^\\s*[\u2022\\-*\u2013]\\s*/, '').trim(); }).filter(Boolean);\n    return (pts.length ? '<ul>' + pts.map(function (p) { return '<li>' + esc(p) + '</li>'; }).join('') + '</ul>' : '')\n      + '<figure><table><caption>' + esc(title.trim()) + '</caption>'\n      + '<thead><tr>' + head.map(function (c) { return '<th scope=\"col\">' + esc(c) + '</th>'; }).join('') + '</tr></thead>'\n      + '<tbody>' + bodyRows.map(tr).join('') + '</tbody>'\n      + (foot ? '<tfoot>' + tr(foot) + '</tfoot>' : '') + '</table>'\n      + (source.trim() ? '<figcaption>' + esc(source.trim()) + '</figcaption>' : '') + '</figure>';\n  }\n  function tableBox() {\n    var d = $('tTitle').value, t = $('tData').value, p = $('tPoints').value, s = $('tSource').value;\n    try { return { html: buildTable(d, t, p, s) }; } catch (e) { return { error: e.message }; }\n  }\n  function drawTablePreview() {\n    var meta = /^(TITLE|POINT|SOURCE)\\t/im;\n    if (meta.test($('tData').value)) {                                   // a table file was pasted: share it out\n      var keep = [], pts = [];\n      $('tData').value.replace(/\\r/g, '').split('\\n').forEach(function (l) {\n        var m = l.match(/^(TITLE|POINT|SOURCE)\\t(.*)$/i);\n        if (!m) { keep.push(l); return; }\n        var k = m[1].toUpperCase(), v = m[2].trim();\n        if (k === 'TITLE') $('tTitle').value = v; else if (k === 'SOURCE') $('tSource').value = v; else pts.push(v);\n      });\n      if (pts.length) $('tPoints').value = pts.join('\\n');\n      $('tData').value = keep.join('\\n').replace(/^\\n+/, '');\n    }\n    var r = tableBox(), filled = $('tData').value.trim();\n    $('tPrev').innerHTML = r.html || '';\n    $('tErr').textContent = filled && r.error ? r.error : ''; $('tErr').className = 'banner' + (filled && r.error ? ' err' : '');\n  }\n  ['tTitle', 'tData', 'tPoints', 'tSource'].forEach(function (id) { $(id).addEventListener('input', drawTablePreview); });\n  $('tCancel').onclick = function () { $('tableDlg').close(); };\n  $('tAdd').onclick = function () {\n    var r = tableBox();\n    if (r.error) { $('tErr').textContent = r.error; $('tErr').className = 'banner err'; return; }\n    $('tableDlg').close();\n    restore();\n    document.execCommand('insertHTML', false, r.html + '<p><br></p>');\n    markDirty(); countWords();\n  };\n  function openTableBox() {\n    ['tTitle', 'tData', 'tPoints'].forEach(function (id) { $(id).value = ''; });\n    $('tSource').value = 'Source: NoResume'; $('tPrev').innerHTML = ''; $('tErr').textContent = ''; $('tErr').className = 'banner';\n    $('tableDlg').showModal(); $('tTitle').focus();\n  }\n  function textToHtml(text) {\n    return String(text).replace(/\\r/g, '').split(/\\n\\s*\\n/).map(function (block) {\n      block = block.trim(); if (!block) return '';\n      var lines = block.split('\\n');\n      if (lines.every(function (l) { return /^\\s*([\u2022\\-*\u2013]|\\d+[.)])\\s+/.test(l); })) {\n        var ordered = /^\\s*\\d/.test(lines[0]);\n        return '<' + (ordered ? 'ol' : 'ul') + '>' + lines.map(function (l) { return '<li>' + esc(l.replace(/^\\s*([\u2022\\-*\u2013]|\\d+[.)])\\s+/, '')) + '</li>'; }).join('') + '</' + (ordered ? 'ol' : 'ul') + '>';\n      }\n      return '<p>' + lines.map(esc).join('<br>') + '</p>';\n    }).join('');\n  }\n\n  // \u2500\u2500 toolbar \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  function inBody() { var s = window.getSelection(); return s.rangeCount && $('body').contains(s.getRangeAt(0).commonAncestorContainer); }\n  var saved = null;\n  document.addEventListener('selectionchange', function () { if (inBody()) saved = window.getSelection().getRangeAt(0).cloneRange(); });\n  function restore() { $('body').focus(); if (saved) { var s = window.getSelection(); s.removeAllRanges(); s.addRange(saved); } }\n  $('toolbar').addEventListener('mousedown', function (e) { if (e.target.closest('button')) e.preventDefault(); });\n  $('toolbar').addEventListener('click', function (e) {\n    var b = e.target.closest('button'); if (!b) return;\n    var cmd = b.getAttribute('data-cmd');\n    restore();\n    if (cmd === 'p' || cmd === 'h2' || cmd === 'h3') document.execCommand('formatBlock', false, '<' + cmd + '>');\n    else if (cmd === 'quote') document.execCommand('formatBlock', false, '<blockquote>');\n    else if (cmd === 'bold' || cmd === 'italic' || cmd === 'undo') document.execCommand(cmd);\n    else if (cmd === 'ul') document.execCommand('insertUnorderedList');\n    else if (cmd === 'ol') document.execCommand('insertOrderedList');\n    else if (cmd === 'clear') { document.execCommand('removeFormat'); document.execCommand('unlink'); }\n    else if (cmd === 'link') {\n      var url = prompt('Link address (https://...)', 'https://');\n      if (url && /^(https?:\\/\\/|mailto:|\\/)/.test(url.trim())) { restore(); document.execCommand('createLink', false, url.trim()); }\n      else if (url) alert('Links need to start with https://');\n    } else if (cmd === 'image') { $('bodyFile').click(); return; }\n    else if (cmd === 'table') { openTableBox(); return; }\n    markDirty(); countWords();\n  });\n  $('bodyFile').onchange = function () {\n    var f = this.files[0]; this.value = '';\n    if (!f) return;\n    var alt = prompt('Describe the picture in a few words (read out to blind visitors and used by Google):', '') || '';\n    upload(f).then(function (r) {\n      restore();\n      document.execCommand('insertHTML', false, '<figure><img src=\"/admin/img/' + r.id + '\" alt=\"' + esc(alt) + '\"></figure><p><br></p>');\n      markDirty();\n    }).catch(function (e) { banner(e.message); });\n  };\n  $('body').addEventListener('paste', function (e) {\n    var cd = e.clipboardData; if (!cd) return;\n    e.preventDefault();\n    var html = cd.getData('text/html'), text = cd.getData('text/plain');\n    var clean = html ? cleanHtml(html) : textToHtml(text);\n    // pasted HTML that lost its paragraph breaks (one big block) is better rebuilt from the plain text\n    if (html && text && (text.match(/\\n\\s*\\n/g) || []).length >= 2 && (clean.match(/<(p|h2|h3|li|blockquote)>/g) || []).length < 2) clean = textToHtml(text);\n    document.execCommand('insertHTML', false, clean);\n    markDirty(); countWords();\n  });\n  $('body').addEventListener('input', function () { markDirty(); countWords(); });\n  document.execCommand('defaultParagraphSeparator', false, 'p');\n\n  // \u2500\u2500 form \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  $('title').addEventListener('input', function () { if (!state.slugTouched) $('slug').value = slugify(this.value); });\n  $('slug').addEventListener('input', function () { state.slugTouched = true; });\n  $('slug').addEventListener('change', function () { this.value = slugify(this.value); });\n  $('excerpt').addEventListener('input', function () { $('excerptCount').textContent = this.value.length; });\n  $('form').addEventListener('input', markDirty);\n  $('form').addEventListener('change', markDirty);\n  $('form').addEventListener('submit', function (e) { e.preventDefault(); });\n  $('coverBtn').onclick = function () { $('coverFile').click(); };\n  $('coverFile').onchange = function () {\n    var f = this.files[0]; this.value = '';\n    if (f) upload(f).then(function (r) { setCover(r.id); markDirty(); }).catch(function (e) { banner(e.message); });\n  };\n  $('coverDel').onclick = function () { setCover(null); markDirty(); };\n  $('newBtn').onclick = function () {\n    if (state.dirty && !confirm('You have unsaved changes. Leave them?')) return;\n    fill({ category: 'Hiring', author_name: state.me, status: 'draft' }); $('title').focus();\n  };\n  $('backBtn').onclick = function () {\n    if (state.dirty && !confirm('You have unsaved changes. Leave them?')) return;\n    state.dirty = false; state.post = null; $('wrap').classList.remove('editing'); $('form').hidden = true; $('empty').hidden = false; drawList();\n  };\n  document.addEventListener('keydown', function (e) {\n    if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 's' && state.post) { e.preventDefault(); save('save'); }\n  });\n  window.addEventListener('beforeunload', function (e) { if (state.dirty) { e.preventDefault(); e.returnValue = ''; } });\n\n  busy(true);\n  loadList().catch(function (e) { $('empty').textContent = e.message; }).then(function () { busy(false); });\n})();\n</script>\n</body>\n</html>\n";
